window.STORY_CHAPTERS["c7e7fc4da951464a6"]={"id":"c7e7fc4da951464a6","lines":[{"uid":"talk.vc.home_time_linel_4#originalText","id":"talk.vc.home_time_linel_4","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我们来午休吧。午餐……你要一起吃吗？","en":"Let us take a lunch break. Would you...care to join me?","ja":"お昼の休憩にしましょう食事……一緒に食べますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_5#originalText","id":"talk.vc.home_time_linel_5","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我喜欢索鲁斯的温暖。总觉得，有种受到疗愈的感觉。","en":"I love Solus's warmth. It feels quite...soothing.","ja":"ソルスの暖かさは好きですどこか、癒やされる気がします"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_7#originalText","id":"talk.vc.home_time_linel_7","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"今天也结束了。见习修女的生活每天都一样呢……","en":"Another day is done. A nun-in-training's life certainly is monotonous.","ja":"今日も一日終わりました修道女見習いの生活は毎日同じですね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_8#originalText","id":"talk.vc.home_time_linel_8","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"晚上不早点睡觉，就会被元老长大人处罚……","en":"If we don't fall asleep quickly at night, the Prime Senator punishes us.","ja":"夜は早く寝ないと元老長様のお仕置きが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_10#originalText","id":"talk.vc.home_time_linel_10","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"呼……呼……嗯？怎么了吗？","en":"Zzz...zzz... Hm?! What is it?","ja":"すぅー、すぅー……ん、なんですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_11#originalText","id":"talk.vc.home_time_linel_11","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我偶尔会想起以前的事情，然后睡不着。那种时候，我就会去黏赛尔。","en":"Sometimes I'm kept wide awake by past memories. Whenever that happens, I snuggle against Fizel.","ja":"時々昔のことを思い出して目が冴えちゃうことがあるんですそんな時は、ゼルにくっつきます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lipia_1#originalText","id":"talk.vc.home_time_lipia_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"早安。我已经做好出发的准备，请随时吩咐。","en":"Good morning. I have sorted out our preparations for departure. I am always at your service.","ja":"おはようございます出立の準備は整っておりますいつでもお申し付けください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lipia_4#originalText","id":"talk.vc.home_time_lipia_4","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"我已经准备好餐点了。做得不好，也请多包涵……","en":"I have prepared some food. It's not the most glamorous, but if you don't mind...","ja":"食事の用意ができましたつたない料理ですがよろしければ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lipia_7#originalText","id":"talk.vc.home_time_lipia_7","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"要小心夜晚的黑暗。说不定会有暗杀者或是暗黑术师的虫潜伏着。","en":"We need to be on the lookout for Assassins and Dark Sorcerers roaming around in the darkness of the night. Those vermin are probably lurking around somewhere.","ja":"夜の闇にはご注意を暗殺者や暗黒術師の放つ虫が潜んでいるかもしれません"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lipia_10#originalText","id":"talk.vc.home_time_lipia_10","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下，已经这么晚了……明明只要您说一声我就会马上过去。","en":"My Lord, why are you up this late in the night... If you call for me, I will be there.","ja":"閣下、このような夜更けに……お呼びくだされば、私の方から参りましたのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_1#originalText","id":"talk.vc.home_time_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"早安～好，该准备开店了。","en":"Morning. Okay. Better get ready to open shop.","ja":"おはようーさて、お店の準備をしないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_2#originalText","id":"talk.vc.home_time_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你还睡喔？反正我看是昨天晚上又熬夜了吧？","en":"Are you still in bed? Let me guess. You pulled another all-nighter?","ja":"まだ寝てるの? どうせ昨日夜更かししたんでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_3#originalText","id":"talk.vc.home_time_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"早上的时候啊，不管多早起，时间总是一眨眼就过了呢～","en":"No matter how early I wake up, time always disappears so quickly in the morning.","ja":"朝って、どんなに早く起きても気がついたら時間が経ってるのよねー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_4#originalText","id":"talk.vc.home_time_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你早上都睡那么晚了现在居然还睡得着，某种意义上也算是种才能了啦。","en":"You stayed in bed so long this morning, and you wanna nap again? In a way, that's a talent.","ja":"朝あれだけ寝たのにまだ寝られるってある意味才能だわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_5#originalText","id":"talk.vc.home_time_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"啊，来得正好！我现在有点忙，你可以帮我吗？","en":"Ooh, perfect timing! I'm kinda busy, can you lend me a hand?","ja":"あ、いいところに! 今ちょっと忙しくてさ手伝ってもらえる? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_6#originalText","id":"talk.vc.home_time_lisbeth_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这个世界的冶炼很有趣呢，一不小心似乎就会沉迷其中。","en":"Blacksmithing in this world is fun! I just might become obsessed.","ja":"この世界の鍛冶は面白いわね思わずのめりこんじゃいそう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_7#originalText","id":"talk.vc.home_time_lisbeth_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天也辛苦你了～晚上就好好休息吧。","en":"Good work today. Make sure you rest up well tonight.","ja":"今日もお疲れさまー夜はゆっくり休みましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_8#originalText","id":"talk.vc.home_time_lisbeth_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"晚上偶尔也会有客人来喔。就算是那种人，还是得好好接待才行。","en":"Sometimes I get customers even at night. But, I have to give them good service, too.","ja":"たまに、夜でもお客さんが来るのよそうした人でも、大事にしないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_9#originalText","id":"talk.vc.home_time_lisbeth_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"……晚上像这样跟你两个人在一起，就会想起在洞窟的那一天呢。","en":"Spending nights together like this... It reminds me of that one night in the cave.","ja":"……夜こうしてふたりでいるといつかの洞窟を思い出しちゃうわね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_10#originalText","id":"talk.vc.home_time_lisbeth_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"总觉得睡不着，来弄杯热牛奶好了。","en":"I just couldn't sleep. Maybe I should make some warm milk.","ja":"なんか目が冴えちゃって暖かいミルクでも作ろうかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_11#originalText","id":"talk.vc.home_time_lisbeth_11","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"啊，已经这么晚了？我稍微调查了一下武器的材料，就弄得太忘我了。","en":"Oh, why am I up so late? Well, I was researching weapons, and I guess I lost track of time.","ja":"あ、もうこんな時間? ちょっと武器の材料を調べてたら夢中になっちゃって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_12#originalText","id":"talk.vc.home_time_lisbeth_12","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"呼～实在是困了。谢谢你陪我到这么晚。","en":"Phew. Okay, now I'm definitely tired. Thanks for staying up with me.","ja":"ふぅ～、さすがに眠くなってきたありがとう遅くまで付き合ってくれて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_1#originalText","id":"talk.vc.home_time_mary_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊快点起床！索鲁斯大人已经高高挂在天上了喔！","en":"Come on, Sister, wake up! Solus is already high in the sky!","ja":"ほら、起きてお姉ちゃん!もうソルス様がお空に上がってるよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_2#originalText","id":"talk.vc.home_time_mary_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"为了让姊姊有活力，早餐我得做好吃一点才行。","en":"It's time for breakfast. I need to cook up something that will give my sister the energy she needs!","ja":"朝ご飯、お姉ちゃんが元気になるようにおいしく作らなくっちゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_3#originalText","id":"talk.vc.home_time_mary_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天脚不怎么疼，所以我得趁机到村里大采购。","en":"My foot doesn't really hurt today. So I need to go to town and do as much shopping as I can.","ja":"今日はあんまり足が痛くないのだから、村に行っていろいろ買い物しなくちゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_4#originalText","id":"talk.vc.home_time_mary_4","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天天气真好。对了！干脆来晒棉被吧！","en":"What a lovely day. I know! Let's give all the beds a good airing!","ja":"今日はいいお天気そうだ! 思い切ってお布団を干しちゃおう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_5#originalText","id":"talk.vc.home_time_mary_5","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"村里的人会顾虑到我的脚不方便，分些食物给我。得感谢他们才行。","en":"The villagers were kind to fetch me food since I can't walk well. I should thank them.","ja":"わたしの足を気遣って村の人が食べ物なんかを分けてくれるの。感謝しないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_6#originalText","id":"talk.vc.home_time_mary_6","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我得送便当给姊姊！她今天应该是在村里工作。","en":"I must bring my sister lunch! I think she's working in the village today.","ja":"お姉ちゃんにお弁当持っていかないと! 今日は村でお仕事しているはずだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_7#originalText","id":"talk.vc.home_time_mary_7","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊好慢喔……──啊！回来了！欢迎回来！","en":"Sister sure is late getting back... Ooh, here she is! Good evening, Sister!","ja":"お姉ちゃん、遅いなあ…………あっ、帰って来た!おかえりなさいっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_8#originalText","id":"talk.vc.home_time_mary_8","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"晚餐的碗盘我来收拾，姊姊妳可以先去洗澡喔。","en":"You can go ahead and bathe without me, Sister. I need to wash the dinner dishes.","ja":"夕ご飯の片付けしちゃうからお姉ちゃんが先にお風呂でいいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_9#originalText","id":"talk.vc.home_time_mary_9","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"虽然已经很晚了，但我好想再跟姊姊多聊一会……","en":"I know it's rather late, but I'd sure love to stay up a little longer and talk with you.","ja":"もう夜遅いけどあと少しだけお姉ちゃんとおしゃべりしたいなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_10#originalText","id":"talk.vc.home_time_mary_10","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊，妳还醒着吗？真是的……不睡觉怎么行？来，我们一起睡吧……","en":"Sister, were you awake all this time? Please, you need to come to bed. Come on, let's sleep together.","ja":"お姉ちゃん、起きてたの?もう……寝なくちゃダメだよほら、一緒に寝よ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_11#originalText","id":"talk.vc.home_time_mary_11","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"呼、呼…………希望姊姊能平安回来……","en":"May the gods bless my sister... and bring her home safe.","ja":"すう、すう…… ……お姉ちゃんが、無事に 帰ってこられますように……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_mary_12#originalText","id":"talk.vc.home_time_mary_12","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我有点睡不着……早上起床时，姊姊也要陪在人家身边，说好了喔。","en":"I'm having a hard time falling asleep... Promise you'll be with me when I wake up. Please?","ja":"なんだか眠れなくて……朝起きても、隣にいてね?きっとだよ、お姉ちゃん"},"kind":"dialogue"},{"uid":"talk.vc.home_time_medina_1#originalText","id":"talk.vc.home_time_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"看你的样子你还没睡醒呢。怎样，要来场比试让你醒过来吗？","en":"Looks like you overslept. So what is it? Did you wake up to confront me?","ja":"寝ぼけた顔をしているなどうだ、立ち合いで目を覚ましてやってもいいぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_medina_4#originalText","id":"talk.vc.home_time_medina_4","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你又无所事事吗？一直这样，很快会被我追上喔。","en":"What do you do in your free time? I'll catch up to you in no time.","ja":"また暇をもて余しているのか?そんなことでは、すぐ私が追い抜くことになるな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_medina_7#originalText","id":"talk.vc.home_time_medina_7","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"一到晚上，我就会想起那些曾经幸福的日子和无法挽回的那些话……","en":"I reminiscence whenever it gets dark outside. About happy days and of those words that can't be taken back...","ja":"夜になると、思い出してしまうんだ幸せだった日々と、取り返せないあの言葉を……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_medina_10#originalText","id":"talk.vc.home_time_medina_10","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"一看就知道我在挥剑吧。明明不想被任何人看到的……","en":"You should be able to understand by looking at the way one handles a sword. Even though I don't want anyone to look at me...","ja":"剣を振っていることくらい見ればわかるだろう誰にも見られたくなかったのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_nergius_integrator_1#originalText","id":"talk.vc.home_time_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"你现在才起床？……是不是昨天晚睡害的啊？","en":"Did you just now awaken? Are you...perhaps regretting staying up so late last night?","ja":"今起きたのですか?……昨日の夜ふかしが祟ったのではないですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_nergius_integrator_4#originalText","id":"talk.vc.home_time_nergius_integrator_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"差不多快中午了……得喂汐抚才行。另外还想帮牠洗个澡呢。","en":"It's almost noon. I need to get Shionade some lunch. And a bath.","ja":"そろそろ昼か……汐撫の食事を用意しないと体も洗ってやりたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_nergius_integrator_7#originalText","id":"talk.vc.home_time_nergius_integrator_7","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"好了，你打算在这时候上哪去呢，代表剑士大人？","en":"Now, tell me. Just where do you think you are going this late, Sir Swordsman Delegate?","ja":"さて、こんな時間からどこへ行こうというのですか代表剣士殿"},"kind":"dialogue"},{"uid":"talk.vc.home_time_nergius_integrator_10#originalText","id":"talk.vc.home_time_nergius_integrator_10","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"……被你看到我在训练啦。毕竟没人知道和平是否又会被破坏。","en":"Ah...I see you've caught me. Well, I was practicing. There's no guarantee peace will last forever.","ja":"……見られてしまいましたか稽古ですよ。またいつ平和が破られるかわかりませんから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_oberon_1#originalText","id":"talk.vc.home_time_oberon_1","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"早安，心情如何？我美丽的蒂塔妮亚。","en":"Morning. Are you well? Lady Titania.","ja":"おはようご機嫌はいかがかな麗しのティターニア"},"kind":"dialogue"},{"uid":"talk.vc.home_time_oberon_4#originalText","id":"talk.vc.home_time_oberon_4","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"来，你看看地面那里。角色都变得那么小，就跟虫子一样呢！","en":"Take a look on the ground! Everyone is so tiny! Like an insect!","ja":"ほら、地上を見たまえキャラクターがあんなに小さくてまるで虫のようじゃないか!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_oberon_7#originalText","id":"talk.vc.home_time_oberon_7","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"跟一群笨蛋共处也是挺累的。想要放松的话，看着她是最好的……","en":"Even idiots get tired. In terms of relaxation, her form is by far the best.","ja":"バカどもの相手をするのも疲れるものだ。リラックスにはやはり彼女の姿が一番だな……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_oberon_10#originalText","id":"talk.vc.home_time_oberon_10","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"我现在很困。有事之后再说。","en":"If you're tired now, then don't push yourself. If you have anything to do, you can save that for later.","ja":"今は眠くて仕方がないんだ用件なら後にしてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_1#originalText","id":"talk.vc.home_time_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"早安－－吃早餐了吗？不可以啦，要吃早餐才行。","en":"Morning! Did you eat breakfast? No? That's no good! You need to eat.","ja":"おはようー朝ご飯食べた?ダメだよ、ちゃんと食べないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_2#originalText","id":"talk.vc.home_time_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"今天是绝佳的探险日呢！今天好像能发现很棒的宝藏。","en":"Today is the perfect weather for an exploration! I think we'll find some great treasure!","ja":"今日は絶好の探検日和だね!いいお宝が見つかりそうだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_4#originalText","id":"talk.vc.home_time_phillia_4","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"今天有点暖和呢。有点明白想睡午觉的心情。","en":"Today's weather is pretty nice and warm, isn't it? I totally get those who would want to take an afternoon nap.","ja":"今日は少しポカポカしてるねお昼寝したくなる気持ちもちょっとわかるなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_5#originalText","id":"talk.vc.home_time_phillia_5","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"呐，我今天试做了便当耶……要一起吃吗？","en":"Hey, I made a lunch box today... Do you want to try it with me?","ja":"ねえ、今日わたしお弁当作ってみたんだけど……一緒に食べない?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_7#originalText","id":"talk.vc.home_time_phillia_7","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"呵呵，出现晚霞的天空会把整个世界染成红色的。我最喜欢了。","en":"Fufu, seeing the sunset cast it's warm glow over the whole world is one of my favorite sights","ja":"ふふ、夕焼けの空って世界全部が赤く染まってわたし大好きなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_8#originalText","id":"talk.vc.home_time_phillia_8","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"那我去洗个澡吧。你、你千万不可以偷看喔……！","en":"Anyhow, shall we get in the bath? D-Don't you dare peak...!","ja":"さてと、お風呂に入っちゃおうかなの、覗いちゃダメだからね…っ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_10#originalText","id":"talk.vc.home_time_phillia_10","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"大半夜，一个人在寂静中渡过的时候，我就会想起以前的事。……所以，你可以陪我吗？","en":"Staying silent in the middle of the night by yourself makes you remember things from the past... So can you stay with me?","ja":"夜中、シーンとした中にひとりでいると、昔のことを思い出すの……だから、一緒にいてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_phillia_11#originalText","id":"talk.vc.home_time_phillia_11","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"嘿嘿……失眠好伙伴的你，要一起跟我去夜晚的散步吗？","en":"Ehehe... If you can't sleep, how about taking a walk at night?","ja":"えへへ……眠れない者同士夜のお散歩にでも行こうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_1#originalText","id":"talk.vc.home_time_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"早安。来吃早餐吧！今天的菜单是什么呢？","en":"Good morning. Shall we do breakfast? What's on the menu today?","ja":"おはようございますさあ、朝ご飯にしましょう今日のメニューはなんですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_2#originalText","id":"talk.vc.home_time_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"今天睡过头了吗？呵呵……跟我一样呢。我也睡了很久呢。","en":"Did you oversleep today? Hehe... I guess that makes two of us. I also managed to get a lot of shut eye.","ja":"今日はお寝坊ですか?ふふ……私と一緒ですね私も、たくさん睡眠を取りました"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_4#originalText","id":"talk.vc.home_time_premiere_4","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"一起吃饼干吧。饼干无论何时都很好吃。","en":"Let's eat cookies together! Cookies are always delicious.","ja":"一緒にクッキーを食べましょうクッキーはいつでもおいしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_5#originalText","id":"talk.vc.home_time_premiere_5","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"睡午觉……我听说过睡眠是很重要的。那我也一起睡吧。","en":"Napping... I've heard that rest is an important thing to have. I will also take a rest.","ja":"お昼寝……睡眠は大事なことだと聞いたことがあります私も一緒に寝ます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_7#originalText","id":"talk.vc.home_time_premiere_7","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"空中出现好多星星。呐……要不要一起观星呢？","en":"Lots of stars dot the night sky. Um... How about we go see them together?","ja":"空にたくさんの星が出ていますあの……一緒に見ませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_8#originalText","id":"talk.vc.home_time_premiere_8","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"看着星星，就会让我想起那时候的事。呵呵……那是我重要的回忆。","en":"Looking at the stars reminds me of that time. Fufu... A very special memory.","ja":"星を見ていると、あの時のことを思い出しますふふ……私の大切な思い出です"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_10#originalText","id":"talk.vc.home_time_premiere_10","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"不是应该要睡了吗？","en":"Shouldn't you be getting some rest?","ja":"睡眠を取らないといけないのではないのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_premiere_11#originalText","id":"talk.vc.home_time_premiere_11","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"睡不着的话，我们就一起躺着吧。这样一定很快就能熟睡了。","en":"If you're tired, then come sleep by my side. That way, you'll be fully rested.","ja":"眠れないのなら、一緒に横になりましょう。そうすれば、きっとぐっすり眠れます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_1#originalText","id":"talk.vc.home_time_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"早安嘿嘿，我做了早餐喔！一起吃吧？","en":"Morning. Ehehe, I made some breakfast. Care to join me?","ja":"おはようえへへ、朝ご飯作ってあるよ一緒に食べよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_2#originalText","id":"talk.vc.home_time_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"啊、啊－－早上有好好练习发声的话，喉咙的状况一整天都会很好喔！","en":"Ah, ah♪ If you practice your vocals in the morning, then your voice will be pitch perfect all day!","ja":"ア、アー♪朝しっかり発声練習しておくと一日ずっと声の調子がいいんだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_4#originalText","id":"talk.vc.home_time_rain_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"天气真好……在这样的日子，飞到空中散步也很开心吧。","en":"What great weather... This is the sort of day for soaring in the skies or even going out for a walk.","ja":"いいお天気……こんな日は、空を飛んで散歩も楽しいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_5#originalText","id":"talk.vc.home_time_rain_5","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"欸，你可以的话要出门吗？邀赛玟三个人一起！","en":"Hey, if it's ok with you how about we go out somewhere? I'll also invite Seven, so it'll be the three of us!","ja":"ねえ、よかったらどこかにお出かけしない?セブンも誘って３人で!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_7#originalText","id":"talk.vc.home_time_rain_7","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"不知不觉外面已经天黑了。该回去了吧。","en":"Before we knew it, it's already pitch black outside. Let's start heading back.","ja":"いつの間にか、外は真っ暗だねそろそろ帰ろっか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_8#originalText","id":"talk.vc.home_time_rain_8","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"方便的话，要不要一起去吃午餐啊？今天赛玟也在喔。","en":"If it is alright with you, would you mind having dinner together? Seven will also be joining today.","ja":"夕ご飯、よかったら一緒に食べていかない?今日はセブンも一緒なの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_10#originalText","id":"talk.vc.home_time_rain_10","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你还没睡啊？……不过，我也一样就是了。","en":"You're still awake? ... I also can't talk about a person's business.","ja":"まだ起きてたの?……って、わたしも人のことは言えないけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rain_11#originalText","id":"talk.vc.home_time_rain_11","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你睡不着吗？那……我给你唱首摇篮曲吧？","en":"If you aren't tired, how about I sing you a lullaby?","ja":"眠れないなら、子守歌を歌ってあげようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_raios_1#originalText","id":"talk.vc.home_time_raios_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"好像睡晚了。看来，昨天的盛宴开得过头了。","en":"It appears I've overslept. Perhaps I carried on a little too heavily during last night's banquet.","ja":"寝過ごしてしまったようだ少々、昨日の饗宴が過ぎてしまったようだな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_raios_4#originalText","id":"talk.vc.home_time_raios_4","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"中午饮酒也别有一番风味，相当不错。","en":"I like day-drinking. It has a certain elegance to it.","ja":"昼から酒というのもなかなか風情があってよいものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_raios_7#originalText","id":"talk.vc.home_time_raios_7","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"呼，终于可以放松了。","en":"Phew. At last, some time to relax.","ja":"ふう、やっとくつろげる時間だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_raios_10#originalText","id":"talk.vc.home_time_raios_10","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"实在是有些困了。虽然我想再喝一点……还是打住吧。","en":"I've gotten sleepy. I would love to drink some more, but I think I'll call it quits.","ja":"さすがに眠くなってきたなもう少し飲みたいが……やめておくか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_1#originalText","id":"talk.vc.home_time_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"早安！从早上就碰到你，感觉今天会有好事发生。","en":"Good morning! Meeting you this early in the morning means that good things will happen today.","ja":"おはよう!朝から君に会えるなんて今日はいいことがありそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_2#originalText","id":"talk.vc.home_time_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"今天感觉外面很舒服，如果可以的话……要不要去哪里喝杯茶呢？","en":"The weather is nice today. If it's fine with you... Would you like to get a drink somewhere?","ja":"今日は外が気持ちよさそうだからよかったら……どこかでお茶でもしないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_4#originalText","id":"talk.vc.home_time_renri_4","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"这个午饭难道是你亲手做的？看起来好好吃……","en":"Did you happen to make that lunch yourself? It looks pretty delicious...","ja":"もしかして、その昼食は君の手作り?おいしそうだなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_5#originalText","id":"talk.vc.home_time_renri_5","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"根据用法，双翼刃可以变得更强。如果我的力量可以变得更强的话……","en":"The Twin Edged Wings will get stronger depending on how you use it. I need to get better...","ja":"雙翼刃は、使い方によってもっと強くなる僕の力量をもっと高めれば……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_7#originalText","id":"talk.vc.home_time_renri_7","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"今天一整天也辛苦你了。明天，要是也能见到你就好了。","en":"Good job today! I hope I can see you tomorrow too.","ja":"今日も一日お疲れ様明日も、君に会えるといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_8#originalText","id":"talk.vc.home_time_renri_8","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"晚饭之后，我想去做一下训练。为了要变强，就算是一点点也好。","en":"I'm think of doing a little training  after dinner. I need to get stronger, even if it's just a little.","ja":"夕食の後は、少し訓練をしようと思うんだ少しでも、強くなるために"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_10#originalText","id":"talk.vc.home_time_renri_10","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……我梦到很让人怀念的事。但是，为什么会感到怀念，我自己也想不明白……","en":"...I had a dream that made me feel nostalgic. But, I don't know why I feel that way...","ja":"……懐かしい夢を見たんだでも、なんでそれが懐かしいのかどうしてもわからない……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_renri_11#originalText","id":"talk.vc.home_time_renri_11","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"像这样晚上小小声地聊着天，缌觉得有点兴奋呢。","en":"You know, sneaking around talking like this gets me a little excited.","ja":"夜中にこうしてひそひそ話をしていると、なんだか少しわくわくしてしまうんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_1#originalText","id":"talk.vc.home_time_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"早安！学长，该起床了！","en":"Good morning, sir! It's time to get up!","ja":"おはようございます! 先輩、起床の時間です! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_2#originalText","id":"talk.vc.home_time_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"请问，我可以跟您一起晨练吗？","en":"May I accompany you on your morning training?","ja":"朝の修練、お付き合いいただいてもよろしいでしょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_3#originalText","id":"talk.vc.home_time_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，您还在休息吗？……那么我身为随侍，就在一旁守候吧。","en":"Mentor, are you still resting? Then, as your page... I shall watch over you.","ja":"先輩、まだお休みですか……なら、傍付きとして見守らせていただきます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_4#originalText","id":"talk.vc.home_time_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我很希望能跟上级修剑士大人一样，拥有单人房……","en":"I wish I had my own private quarters, like the elite disciples.","ja":"上級修剣士殿のように個室をいただけるとうれしいのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_5#originalText","id":"talk.vc.home_time_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"没想到居然能在餐厅遇见您……我很高兴。","en":"I'm honored! I wasn't expecting to see you in the dining hall.","ja":"食堂でお会いできるなんて思っていなかったので……うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_6#originalText","id":"talk.vc.home_time_ronye_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天来吃便当吧。我会跟缇洁一起做的！","en":"Let's have a picnic today. Tiese and I will make the lunch!","ja":"今日はお弁当にしましょうティーゼと一緒に作りますね! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_7#originalText","id":"talk.vc.home_time_ronye_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"不知不觉就到了这个时间……或许会被阿滋利卡老师骂……","en":"When did it get so late... Ms. Azurika might scold me.","ja":"いつのまにかこんな時間……アズリカ先生に叱られてしまうかも……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_8#originalText","id":"talk.vc.home_time_ronye_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"晚上跟缇洁和芙蕾妮卡聊天，常常会不小心熬夜。","en":"Sometimes I accidentally stay up all night talking with Tiese and Frenica.","ja":"夜はティーゼやフレニーカとおしゃべりして、ついつい夜更かししてしまうんです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_9#originalText","id":"talk.vc.home_time_ronye_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"晚上都会跟缇洁进行模拟战。或许我多少也有变强……吧。","en":"Tiese and I play-wrestle at night. I think we've both gotten stronger from it.","ja":"夜、ティーゼと模擬戦をやってるんです少しだけ強くなったかも、です"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_10#originalText","id":"talk.vc.home_time_ronye_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您在这种时间外出，会被老师们骂的……","en":"If we go outside this late, our teachers will be livid.","ja":"こんな時間に外出されては先生方のお怒りが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_11#originalText","id":"talk.vc.home_time_ronye_11","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我知道一旦熬夜，明天就会很辛苦。但是……","en":"I understand that staying up all night makes the next day difficult. However...","ja":"夜更かしすると、明日が辛いということは、わかっているのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_ronye_12#originalText","id":"talk.vc.home_time_ronye_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……我想睡觉了。晚安了，学长。","en":"I'm sleepy. Goodnight, Mentor.","ja":"……眠くなってきましたおやすみなさい、先輩"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rosalia_1#originalText","id":"talk.vc.home_time_rosalia_1","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"嗯……已经早上了……？我还要再睡，你先走吧。","en":"Mm...morning already? I'm gonna stay in bed. You go on ahead without me.","ja":"ん……もう朝……?アタシはまだ寝てるから先に行ってなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rosalia_4#originalText","id":"talk.vc.home_time_rosalia_4","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"我的午餐在哪？你当然有帮我准备吧？","en":"Where is my lunch? You have cooked me lunch, I hope?","ja":"アタシの食事はどこ?当然用意してあるんでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rosalia_7#originalText","id":"talk.vc.home_time_rosalia_7","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"那我先去洗澡啦。你给我在外面守着。","en":"Well, I'll have the first bath. You stand guard.","ja":"それじゃ、先にお風呂に行くわあんたは見張ってなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_rosalia_10#originalText","id":"talk.vc.home_time_rosalia_10","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"居然大半夜的跑到淑女床上……你还真有胆啊。","en":"Intruding on a lady at night? You've got some nerve.","ja":"深夜にレディのベッドに来るなんて……なかなか度胸があるじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_1#originalText","id":"talk.vc.home_time_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"早安。昨天睡得还好吗？","en":"Good morning! Did you sleep well?","ja":"おはよう昨日はよく眠れた?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_2#originalText","id":"talk.vc.home_time_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"早上看见阳光我就会感到安心，庆幸自己又多迎接了一天的到来。","en":"Whenever I see the sun's morning rays I always feel cozy and safe. It means I made it to see another day.","ja":"朝、おひさまの光を見るとほっとするのまた、今日を迎えられたって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_4#originalText","id":"talk.vc.home_time_sachi_4","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"差不多该吃午餐了吧？方便的话，你要不要跟我一起吃？","en":"Want to eat lunch soon? I can join you, if you'd like.","ja":"そろそろお昼ご飯にする?よかったら、一緒に食べない?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_5#originalText","id":"talk.vc.home_time_sachi_5","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"在空间里睡午觉……对我来说太可怕了，我做不到啦。","en":"Napping in the middle of a field... I'd be too scared to try that.","ja":"フィールドでお昼寝なんて……私には怖くてできないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_7#originalText","id":"talk.vc.home_time_sachi_7","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"今天也平安回来了呢。呵呵，多亏有大家的帮忙。","en":"I managed to come home in one piece again! Hehe, thanks, everyone.","ja":"今日も無事に帰ってこられたねふふ、みんなのおかげ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_8#originalText","id":"talk.vc.home_time_sachi_8","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"晚上会出现很强的怪物，所以不要外出比较好喔。","en":"Stronger monsters come out at night, so you should stay indoors.","ja":"夜は強いモンスターが出るから外には出ないほうがいいよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_10#originalText","id":"talk.vc.home_time_sachi_10","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"……我有点睡不着。呐，我可以……握着你的手吗？","en":"Hey, um...I can't sleep. Can I, uh, hold your hand?","ja":"……ちょっと、眠れなくてねえ、手を握っても……いい?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sachi_11#originalText","id":"talk.vc.home_time_sachi_11","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"只要跟你在一起，我就能安稳入睡。谢谢你，晚安……","en":"Thanks for being with me. Now I know I'll sleep soundly.","ja":"君と一緒なら、ゆっくり眠れそうありがとう、おやすみ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sakuya_1#originalText","id":"talk.vc.home_time_sakuya_1","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"早安。嗯～真是舒爽的早晨呢。","en":"Good morning. Mmm, what a lovely morning.","ja":"おはよううーん、気持ちのいい朝だな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sakuya_4#originalText","id":"talk.vc.home_time_sakuya_4","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"刚好正午了呢。我这有一瓶好酒，要不要一起喝？","en":"It's just about lunchtime now. I just got in some great wine. Wanna have a drink with me?","ja":"ちょうどお昼時だなうまい酒があるんだが一緒にどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sakuya_7#originalText","id":"talk.vc.home_time_sakuya_7","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"你要睡了吗？那就好好休息吧。","en":"Going to bed already? Well, rest up.","ja":"もう寝るのか?ゆっくり休んでくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sakuya_10#originalText","id":"talk.vc.home_time_sakuya_10","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"我有些事情要处理，于是就弄到这么晚了。","en":"I had some odds and ends I wanted to take care of... And before I knew it, the moon was out.","ja":"少々やることがあってなこんな時間になってしまったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_1#originalText","id":"talk.vc.home_time_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……早安，虽然大家都已经起来了。","en":"...Good morning. Everyone is already awake.","ja":"……おはようみんなはもう起きてるけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_2#originalText","id":"talk.vc.home_time_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"不吃早餐吗？","en":"You aren't going to eat breakfast?","ja":"朝食、食べないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_4#originalText","id":"talk.vc.home_time_scheta_4","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我看起来很困？……才没这种事。","en":"Am I sleepy? ... Not at all.","ja":"私が、眠そう?……そんなことはないんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_5#originalText","id":"talk.vc.home_time_scheta_5","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"你真是个不可思议的人。明明看起来很坚硬，但又好像有哪里很软弱……","en":"You're a strange one. Stubborn, yet gentle...","ja":"あなたは不思議な人ね硬そうなのに、どこか柔らかそう……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_7#originalText","id":"talk.vc.home_time_scheta_7","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"这黑百合，就跟我一样……就只是特化了斩击。","en":"This Black Lily... Is specialized to cut.","ja":"この黒百合は、私そのもの……斬ることだけに特化しているの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_8#originalText","id":"talk.vc.home_time_scheta_8","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"晚餐就好好地吃吧。不吃饱明天你可战斗不了。","en":"Make sure to eat a proper dinner. Otherwise you won't be able to fight tomorrow.","ja":"夕食はしっかり食べて明日、戦えなくなってしまうから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_10#originalText","id":"talk.vc.home_time_scheta_10","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……都这么晚了，什么事？","en":"...What do you want at this hour?","ja":"……こんな夜更けに、なに?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_scheta_11#originalText","id":"talk.vc.home_time_scheta_11","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"夜晚总让我的紧张缓和下来……不要随意接近我，我可能会不小心斩了你。","en":"Don't let down your guard... even at night. That's how you end up getting cut.","ja":"夜は緊張を解いているから……あまり不用意に近づかないで斬ってしまうかもしれない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_1#originalText","id":"talk.vc.home_time_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"好了，快起床。祈祷的时间到了。","en":"Come up, wake up. It's time for prayers.","ja":"ほら、起きてお祈りの時間よ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_2#originalText","id":"talk.vc.home_time_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"难得你已经起床了呢。呵呵，真了不起。","en":"Well, you're sure up early! Hehe. Good boy.","ja":"珍しく、ちゃんと起きてるのねふふ、えらいえらい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_4#originalText","id":"talk.vc.home_time_selka_4","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"来，便当。你去对面跟其他孩子一起吃吧。","en":"Here's your lunch. Let's eat with the others over there.","ja":"はい、お弁当向こうで、ほかの子と一緒に食べましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_5#originalText","id":"talk.vc.home_time_selka_5","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"一不留神就跑去睡午觉……真是的，拿你没办法！","en":"There you go, napping again! I swear, the minute I turn my back...","ja":"油断するとすぐ昼寝してるわね……まったく、しょうがないんだから!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_7#originalText","id":"talk.vc.home_time_selka_7","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"欢迎回来。洗澡水已经烧好了，你先去洗吧。","en":"Welcome back. The bath is ready. You go on in ahead of me.","ja":"おかえりお風呂湧いてるから先に入っちゃって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_8#originalText","id":"talk.vc.home_time_selka_8","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"别浪费灯油，赶紧睡觉吧。要确实把灯熄掉喔。","en":"We should turn in soon, I don't want to waste lamp oil.","ja":"油がもったいないからそろそろ寝ましょう灯りはちゃんと消してね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_10#originalText","id":"talk.vc.home_time_selka_10","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你睡不着吗？那……我给你唱首摇篮曲吧？","en":"You can't sleep? Then...I'll sing you a lullaby.","ja":"眠れないの?じゃあ……子守唄を歌ってあげましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_selka_11#originalText","id":"talk.vc.home_time_selka_11","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你不睡觉没关系，但是要保持安静，不然会吵醒大家的。","en":"You may stay up, as long as you stay quiet. I don't want you waking the others.","ja":"起きていてもいいけど静かにねみんなが起きちゃうから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_1#originalText","id":"talk.vc.home_time_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"早安－－！真是的，你还在睡吗？真是只爱睡虫！","en":"Good morning! You're still asleep? Sleepyhead!","ja":"おはよー!まったく、まだ寝てるの?お寝坊さんね!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_2#originalText","id":"talk.vc.home_time_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"脑袋最会活动的时间就是早上了！快点，别发呆了快一起吃饭吧！","en":"The brain works the most in the morning! Don't go dazing off, let's go get some food!","ja":"脳が最も働くのは朝なのよ!ほら、ぼーっとしてないで一緒にご飯よ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_4#originalText","id":"talk.vc.home_time_seven_4","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"总觉得你身边聚了很多有趣的人耶。这有观察的价值喔。","en":"Looks like a couple of interesting people have gathered around you. This is a sight to be seen.","ja":"なんか、あなたの周りには興味深い人間が集まってくるわねこれは観察しがいがあるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_5#originalText","id":"talk.vc.home_time_seven_5","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"偶尔也要尽情地伸展下羽翼呢！来，我们去玩吧！","en":"Sometimes you gotta stretch out your wings! What about it - let's go hang out!","ja":"たまには、ぱーっと羽を伸ばさないとね!さあ、遊びに行くわよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_7#originalText","id":"talk.vc.home_time_seven_7","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"今天也辛苦啰。都累了，差不多该休息了吧？","en":"You did quiet a lot today. So you must be tired - how about we take a rest?","ja":"今日はお疲れ様疲れたし、そろそろ休みましょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_8#originalText","id":"talk.vc.home_time_seven_8","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"好了，今天的午餐是什么呢？午餐是伶茵做给我吃的喔！","en":"Anyways, what should we do about dinner tonight? Rain will be cook for us!","ja":"さて、今日の夕ご飯は何かしら?レインが作ってくれるのよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_10#originalText","id":"talk.vc.home_time_seven_10","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"……怎么了？睡不着吗……那，好了，过来我身边吧。","en":"....What happended? If you aren't... sleepy, then come over here by me.","ja":"……どうしたの?眠れないの……だったら、ほらあたしのそばに来て"},"kind":"dialogue"},{"uid":"talk.vc.home_time_seven_11#originalText","id":"talk.vc.home_time_seven_11","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"你不好好睡的话，明天会什么都做不了喔！","en":"If you don't get any sleep, then you won't be able to do anything tomorrow!","ja":"ちゃんと寝ないと、明日なんにもできなくなっちゃうわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_1#originalText","id":"talk.vc.home_time_shasta_1","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"这里的阳光果然很弱吧。听说人界比这里更明亮……","en":"Just as I thought, the light is weaker here. I hear that the Human Empire is brighter...","ja":"やはり、日の光が弱いな人界は、これよりもずっと明るいと聞くが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_2#originalText","id":"talk.vc.home_time_shasta_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"一大清早就这么有精神。记得小心不要太勉强自己，弄坏自己身体喔？","en":"You wake up early and train hard, but don't over do it. Got it?","ja":"朝早くから精が出るなだが、あまり無理をして体を壊すなよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_4#originalText","id":"talk.vc.home_time_shasta_4","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"最近能认真比试的对手也减少了，这样下去只会一直退步下去。","en":"There haven't been any serious contenders lately. That's one way your skills can get sloppy.","ja":"最近は、本気で立ち合える相手も減ってしまってなこれでは腕が鈍る一方だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_5#originalText","id":"talk.vc.home_time_shasta_5","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"能够用餐是一件很幸福的事。我希望将来可以创造一个不用担心食物的世界……","en":"Having food is something to rejoice about. Someday, I want to live in a world where nobody has to worry about when their next meal is...","ja":"食事があるというのは、幸せだないつか、誰もが食に困らぬ世界にしたいものだが……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_7#originalText","id":"talk.vc.home_time_shasta_7","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"别这么拘谨。这里只有我和你，我们就放轻松点吧。","en":"Lighten up. It's only me and you here. You can talk to me more casually now.","ja":"そう固くなるなここには俺とお前のふたりきりだもっと気軽に話してくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_8#originalText","id":"talk.vc.home_time_shasta_8","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"怎样，你也来喝一杯吗？虽然是便宜的红酒，但味道不差喔。","en":"What do you say? A glass for yourself as well? The wine is on the cheaper side of things but the taste isn't bad.","ja":"どうだ、お前もやるか安物のワインだが、味は悪くないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_10#originalText","id":"talk.vc.home_time_shasta_10","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"都这种时间了还在工作吗？你的情报是很有用，但是希望你能把自己的安全放在第一位。","en":"You're still working at this hour? Your intel really is useful, but your safety comes first.","ja":"こんな時間まで仕事かお前の情報は助かるが、まずは自分の安全を第一に、な"},"kind":"dialogue"},{"uid":"talk.vc.home_time_shasta_11#originalText","id":"talk.vc.home_time_shasta_11","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"能休息的时候就休息吧。敌人不一定只有人界军而已。","en":"Rest when you have the chance. Human Soldiers aren't the only enemies we have to worry about.","ja":"休めるときに休んでおけ敵は人界軍だけとは限らんのだから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_1#originalText","id":"talk.vc.home_time_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"早安。早上都是毕娜叫我起床的喔。","en":"Good morning. Pina always wakes me up, you know.","ja":"おはようございます朝は、ピナが起こしてくれるんですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_2#originalText","id":"talk.vc.home_time_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呵呵，你睡到头发都翘起来了。我现在就帮你弄平喔。","en":"Hehe. You have a cowlick. Here, I'll fix it.","ja":"ふふ、寝癖がついてます今なおしますね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_3#originalText","id":"talk.vc.home_time_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"要不要一起吃早餐呢？今天是吃三明治。","en":"Want to have breakfast with me? I'm having sandwiches.","ja":"朝ごはん、いっしょにどうですか? 今日はサンドイッチです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_4#originalText","id":"talk.vc.home_time_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"睡午觉啊……好像很舒服呢。","en":"You're napping... You look so peaceful.","ja":"お昼寝ですか……気持ちよさそうですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_5#originalText","id":"talk.vc.home_time_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我要跟毕娜去散步。你要一起去吗？","en":"I'm going to go walk Pina. Would you like to come with me?","ja":"ちょっとピナとお散歩してきます一緒に行きますか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_6#originalText","id":"talk.vc.home_time_silica_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"前一阵子，我被问到是不是还没有《天职》……我有那么小吗？","en":"Earlier today, someone asked me if I didn't have my \"Calling\" yet. Do I really look that young?","ja":"この間、まだ《天職》に就いてないのって聞かれちゃいました……あたし、そんなに小さいですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_7#originalText","id":"talk.vc.home_time_silica_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"欢迎回来。晚饭做好啰……我一直很想这样说说看呢。","en":"Welcome back! Dinner's ready... Hehe, I've always wanted to say that.","ja":"おかえりなさいご飯できてますよ……っていつか言ってみたかったんです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_8#originalText","id":"talk.vc.home_time_silica_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"风吹得森林沙沙作响，听起来像是某种生物鸣叫。","en":"The trees in the forest are rustling. It almost sounds like birds.","ja":"風で森がざわめいてますね生き物の声みたいに聞こえます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_9#originalText","id":"talk.vc.home_time_silica_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你今天过得怎么样呢？不介意的话，请说给我听吧。","en":"So, how was your day? Wanna talk about it?","ja":"今日はどんな日でした? よかったら、教えてください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_10#originalText","id":"talk.vc.home_time_silica_10","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呼……呼……嗯嗯，不行啦，毕娜……","en":"Zzz...zzz...mm... Pina, stop...","ja":"すー、すー……んん、ダメだよピナ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_11#originalText","id":"talk.vc.home_time_silica_11","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我今天好像有点睡不着……要不要出去散一下步呢？","en":"I don't think I can sleep tonight. Want to go for a little walk?","ja":"今日はちょっと眠れないかも……少しだけ、お散歩に行きませんか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_silica_12#originalText","id":"talk.vc.home_time_silica_12","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你现在还醒着，身体吃得消吗？可不要太勉强自己喔。","en":"Is it okay for you to be up this late? Please, don't overwork yourself.","ja":"まだ起きてて大丈夫ですか? あんまり無理をしないでくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_1#originalText","id":"talk.vc.home_time_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"早安。好了，快起床！你睡太久了啦！","en":"Good morning. Come on, get up! You're being lazy, you know?","ja":"おはようほら、起きなさい! ちょっと寝すぎよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_2#originalText","id":"talk.vc.home_time_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"好大的呵欠啊……你好歹遮一下吧？","en":"What an epic yawn... Some people cover their mouths, you know?","ja":"大きいあくびね……一応、隠すくらいしたら? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_3#originalText","id":"talk.vc.home_time_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"唔、唔嗯……昨天狩猎到很晚，所以我再睡一下……","en":"Mm, nah... I was up late last night hunting, so I'm gonna take a little nap.","ja":"う、ううん……昨日は遅くまで狩りをしてたからもうちょっと寝る……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_4#originalText","id":"talk.vc.home_time_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"已经中午啦。差不多来开饭吧？","en":"It's noon already? Want some lunch?","ja":"もうお昼かそろそろご飯にする? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_5#originalText","id":"talk.vc.home_time_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"今天的日照很强呢……眼睛好像有点痛。","en":"The sun sure is bright today. My eyes hurt.","ja":"今日は日差しが強いわね……目がちょっと痛いかも"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_6#originalText","id":"talk.vc.home_time_sinon_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你还睡？真亏你这么能睡耶……","en":"Sleeping again? Wow. I'm impressed.","ja":"また寝るの? よくそれだけ眠れるわね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_7#originalText","id":"talk.vc.home_time_sinon_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你晚上要干嘛？有空的话，要不要一起登录游戏？","en":"Any plans tonight? Wanna stay in with me?","ja":"夜はどうするの? よかったら、一緒にインしない? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_8#originalText","id":"talk.vc.home_time_sinon_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"夜晚很安静，我很喜欢。因为我不习惯吵杂的地方……","en":"I love night time because it's nice and quiet. I don't do well in noisy places.","ja":"夜は静かで好きなのうるさいところは、苦手だから……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_9#originalText","id":"talk.vc.home_time_sinon_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"果然，现在睡觉还是有点早呢。我们再聊一会吧。","en":"Yeah, it's still too early to go to sleep. Let's stay up and talk a bit more.","ja":"やっぱり、寝るには少し早いわよねもうちょっと、おしゃべりしましょ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_10#originalText","id":"talk.vc.home_time_sinon_10","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……我作了有点可怕的梦。但不要紧的，只要看到你那张脸，害怕的心情就烟消云散了。","en":"I had a bad dream...but I'm okay now. Seeing you made all the scary thoughts disappear.","ja":"……ちょっと怖い夢を見ちゃったでも平気、あんたの顔を見たら怖いのもどこかに行っちゃったわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_11#originalText","id":"talk.vc.home_time_sinon_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"已经这么晚了……虽然我还想再玩一下，不过真的该睡了吧。","en":"Wow, look how late it is. I'd like to stay up more, but we really should sleep.","ja":"もうこんな時間……もうちょっと遊びたいけどさすがに寝ようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sinon_12#originalText","id":"talk.vc.home_time_sinon_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你睡不着吗？……我也是。我们，稍微聊个天吧。","en":"You can't sleep? Neither can I. Wanna talk for a bit?","ja":"眠れないの? ……私も同じ少し、話をしましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_siune_1#originalText","id":"talk.vc.home_time_siune_1","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"早安。呵呵，瞧你一脸睡意……","en":"Good morning, sleepy-head.","ja":"おはようございますふふ、眠そうな顔……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_siune_4#originalText","id":"talk.vc.home_time_siune_4","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"今天就在外面吃午餐吧。","en":"Let's eat lunch outside today.","ja":"今日は、外でお昼ご飯食べましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_siune_7#originalText","id":"talk.vc.home_time_siune_7","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"今天也辛苦你了。明天也……请多指教喔。","en":"Today was another good day. See you again tomorrow?","ja":"今日も一日お疲れさま明日も……よろしくお願いしますね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_siune_10#originalText","id":"talk.vc.home_time_siune_10","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"你还醒着啊？那么……我来陪你睡吧。","en":"You're still awake? Here...you can sleep with me.","ja":"まだ起きてたの?じゃあ……一緒に寝ましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_1#originalText","id":"talk.vc.home_time_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"已经是早上了，醒醒吧。会迟到喔？","en":"It's morning. Get up. Do you want to be late?","ja":"もう朝だ、目を覚ませ遅刻するぞ? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_2#originalText","id":"talk.vc.home_time_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"接下来要进行晨练。你要是有空，就过来。","en":"I'm about to go to my morning training. If you have time, come with me.","ja":"これから朝の稽古だ時間があるなら、お前も来い"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_3#originalText","id":"talk.vc.home_time_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……你还没睡醒呢。全身都是破绽喔，呵呵。","en":"You're still half-asleep. Hehe, you're just asking to be clobbered.","ja":"……まだ寝ぼけているな隙だらけだぞ、ふふっ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_4#originalText","id":"talk.vc.home_time_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"中午的工作就做到这。傍晚再拜托你了。","en":"This ends your afternoon tasks for the day. I'll see you again in the evening.","ja":"昼の仕事はここまでだまた夕方、よろしく頼む"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_5#originalText","id":"talk.vc.home_time_sortiliena_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我正好准备完餐点，你要吃吗？","en":"I just finished preparing lunch. Care to join me?","ja":"ちょうど食事ができたところだ食べていくか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_6#originalText","id":"talk.vc.home_time_sortiliena_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你训练的状况如何？不只是剑，神圣术也要好好学习喔。","en":"How are your studies going? Make sure you practice the Sacred Arts as well as the sword.","ja":"調子はどうだ? 剣だけじゃなく、神聖術もしっかり学べよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_7#originalText","id":"talk.vc.home_time_sortiliena_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"可别让今日的疲劳累积到明天，休息也是种重要的修行。","en":"Don't let today's exhaustion carry over to tomorrow. Rest is a very important part of work.","ja":"今日の疲れは、明日に残すなよ休むのも大事な修行だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_8#originalText","id":"talk.vc.home_time_sortiliena_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"晚上像这样跟你聊天，让我有种不可思议的感觉。","en":"Whenever we talk at night like this, I always feel a strange sensation.","ja":"夜、こうしてお前と話をしていると不思議な感覚を覚えるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_9#originalText","id":"talk.vc.home_time_sortiliena_9","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你要出门吗？已经超过门禁时间了喔？","en":"Going out at this hour? But it's well past curfew!","ja":"これから外出するのか? 門限はもう過ぎているぞ? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_10#originalText","id":"talk.vc.home_time_sortiliena_10","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……怎么，睡不着吗？就算想训斥，由同样醒着的我来说，应该也没说服力吧。","en":"You can't sleep? I would admonish you... but as I can't sleep myself, that would be hypocritical.","ja":"……どうした、眠れないのか? ダメだ、と同じく起きている私が言っても、説得力がないか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_11#originalText","id":"talk.vc.home_time_sortiliena_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"夜深至此，却不期然地清醒了呢。我去挥一下剑。","en":"Pity to wake up at a time like this. I think I'll go get in a few practice-swings.","ja":"こんな時間に、目が覚めてしまってな少し、剣を振ってくる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_12#originalText","id":"talk.vc.home_time_sortiliena_12","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我也曾有无法成眠的夜晚。所以你不要勉强自己，说出来心情就会平静些。","en":"I used to have trouble sleeping, too. So don't force it. If we just talk for a while, you will easily drift off.","ja":"眠れない夜は、私にもあっただから無理をするな話をすれば、少し落ち着くぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_1#originalText","id":"talk.vc.home_time_sortiliena_child_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"来，开始晨练啰！","en":"Okay, let's begin our morning training!","ja":"さあ、朝の修練を始めるぞ! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_2#originalText","id":"talk.vc.home_time_sortiliena_child_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽然有时候还想睡觉……但不能说那种话！","en":"I do get sleepy sometimes... But I can't let myself focus on that!","ja":"確かに眠い時もあるけど……そんなことは言ってられないんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_4#originalText","id":"talk.vc.home_time_sortiliena_child_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"下午我想要研究武器。","en":"I was thinking I'd spend the afternoon studying weapons.","ja":"午後からは、武器の研究をしようと思ってるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_5#originalText","id":"talk.vc.home_time_sortiliena_child_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天去森林，研究在那里的战斗方法吧。","en":"I was thinking I'd go into the forest today to study how one should fight amidst the trees.","ja":"今日は森に行って、そこでの戦い方を研究しよう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_7#originalText","id":"talk.vc.home_time_sortiliena_child_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我再练一下……我要早点变强才行。","en":"I want to practice just a bit more. I must get stronger as quickly as possible.","ja":"もうちょっとやってから……一日も早く、強くならなくちゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_8#originalText","id":"talk.vc.home_time_sortiliena_child_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"真的累了。我得好好吃饭才行。","en":"Now that was incredibly tiring. I must make sure I eat my supper.","ja":"さすがに疲れちゃったご飯、ちゃんと食べないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_10#originalText","id":"talk.vc.home_time_sortiliena_child_10","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……我常常，会像这样在半夜醒来，然后想很多事情。","en":"Sometimes I wake up in the middle of the night like this. There are just too many things on my mind.","ja":"……時々、こうやって夜中に目が覚めてしまうんだいろいろ考えてしまって"},"kind":"dialogue"},{"uid":"talk.vc.home_time_sortiliena_child_11#originalText","id":"talk.vc.home_time_sortiliena_child_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"明天也要早起，真的该睡了。","en":"I must sleep. I have another early morning tomorrow.","ja":"明日の朝も早いんだもう寝ないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_1#originalText","id":"talk.vc.home_time_strea_1","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"早安……你起的真早～我再睡一下好了～","en":"Good morning... You're up early, eh? I think I want to rest just a little longer...","ja":"おはよう……起きるの早いんだねーアタシはもうちょっと寝るー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_2#originalText","id":"talk.vc.home_time_strea_2","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"昨天熬夜了……再让我多睡一下嘛～","en":"I was up late last night... Please let me sleep a little longer...","ja":"昨日夜更かししちゃったから……もうちょっと寝かせてー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_4#originalText","id":"talk.vc.home_time_strea_4","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"欸欸，一起去吃午饭嘛！我找到了一家很好吃的店喔！","en":"Hey, hey, let's go get some lunch together! I found a really good restaurant!","ja":"ねえねえ、お昼ご飯一緒に食べに行こうよ!おいしいお店、見つけたんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_5#originalText","id":"talk.vc.home_time_strea_5","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"啊，要睡午觉吗？那我也跟你一起睡－－","en":"Ah, are you going to take a nap? If you are, I'll join you then.","ja":"あ、お昼寝するの?それじゃアタシも一緒に寝るー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_7#originalText","id":"talk.vc.home_time_strea_7","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"咦？现在还很早啊。要不要再玩一下？","en":"Eh, it's still pretty early. How about we hang around a little longer?","ja":"えー、まだまだ時間は早いよもうちょっと遊ぼう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_8#originalText","id":"talk.vc.home_time_strea_8","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"总觉得夜晚的气氛很棒。有种大人的感觉。","en":"The night time ambince is great. Makes me feel like an adult.","ja":"夜の雰囲気って、なんかいいよねオトナって感じがするし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_10#originalText","id":"talk.vc.home_time_strea_10","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"你这个时间还醒着吗？呵呵，我也一样。来，过来这里。","en":"You're still awake at this hour? Fufu, looks like that makes both of us. Come over here.","ja":"こんな時間まで起きてるの?ふふ、アタシと一緒だねほら、こっちに来て"},"kind":"dialogue"},{"uid":"talk.vc.home_time_strea_11#originalText","id":"talk.vc.home_time_strea_11","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"今天还是去睡了吧。虽然还有很多话想说，但是明天还有事吧。","en":"Shall we get some sleep? I wanted to talk a little longer, but there's always tomorrow for that.","ja":"さすがに、もう寝ようかまだまだお話ししてたいけど明日があるもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_1#originalText","id":"talk.vc.home_time_subtilizer_1","speaker":{"ja":"サトライザー"},"text":{"ja":"朝になっても、この世界の淀んだ空気は変わらんな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_subtilizer_2#originalText","id":"talk.vc.home_time_subtilizer_2","speaker":{"ja":"サトライザー"},"text":{"ja":"ダークテリトリーという名の通り夜が明けても薄暗いところだ"},"kind":"dialogue"}]};
